  "gowm-v0.4/extension-provider-manifest.schema.json": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "urn:gowm:v0.4:extension-provider-manifest",
    "type": "object",
    "additionalProperties": false,
    "required": [
      "providerId",
      "providerVersion",
      "operations"
    ],
    "properties": {
      "providerId": {
        "type": "string"
      },
      "providerVersion": {
        "type": "string"
      },
      "operations": {
        "type": "array",
        "minItems": 1,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "operationId",
            "operationVersion",
            "maturity",
            "inputSchemaFile",
            "inputSchemaHash",
            "outputSchemaFile",
            "outputSchemaHash",
            "scopePolicy",
            "dataSnapshot"
          ],
          "properties": {
            "operationId": {
              "type": "string"
            },
            "operationVersion": {
              "type": "string"
            },
            "maturity": {
              "enum": [
                "EXPERIMENTAL",
                "PREVIEW",
                "STABLE",
                "DEPRECATED"
              ]
            },
            "inputSchemaFile": {
              "type": "string"
            },
            "inputSchemaHash": {
              "type": "string",
              "pattern": "^sha256:[0-9a-f]{64}$"
            },
            "outputSchemaFile": {
              "type": "string"
            },
            "outputSchemaHash": {
              "type": "string",
              "pattern": "^sha256:[0-9a-f]{64}$"
            },
            "scopePolicy": {
              "enum": [
                "DATA_SCOPE_REQUIRED",
                "DATASET_SCOPE_REQUIRED"
              ]
            },
            "dataSnapshot": {
              "enum": [
                "REQUIRED",
                "OPTIONAL"
              ]
            }
          }
        }
      }
    }
  },
